-- Literal dialogue/hand-ins only; full-chain limitations: docs/coldain-quest-chains.md.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1416, item2 = 1426 }) then
    e.self:Say("Why thank you, " .. e.other:GetCleanName() .. ", I haven't tasted snow bunny stew this good in quite some time. Be a dear and take this back to Mordin for me.")
    e.other:SummonItem(1423)
    e.other:AddEXP(100000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  elseif item_lib.check_turn_in(e.trade, { item1 = 1426 }) then
    e.self:Say("Thanks for the Snow Bunny Stew, " .. e.other:GetCleanName() .. ".")
    e.other:AddEXP(5000)
    e.other:Faction(406, 10, 0)
    e.other:Faction(405, 10, 0)
    e.other:Faction(419, -30, 0)
    e.other:Faction(448, -30, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
